def simulate(I):
    bg=I[0][0]
    objs=[(c,cs) for c,cs in comps(I,bg) if len(cs)>1]
    singles=[(cc,(y,x)) for cc,(y,x) in [(cc,c[0]) for cc,c in comps(I,bg) if len(c)==1]]
