        c2=min(y for y,x in o2[1]); d2=min(x for y,x in o2[1])
        return max(abs(a-c2),abs(b-d2))  # chebyshev between origins
    import heapq
    # repeatedly attach smallest unplaced object to closest placed cluster greedily by min movement
    unplaced=list(objs)
    while unplaced:
        # choose object whose minimal movement to join existing cluster (or stay) is smallest
        cands=[]
        for o in unplaced:
            others=[p for p in placed]
            if not others:
                cands.append((0,o,None))
                continue
            best=None
            for po in others:
                # movement = min shift placing o adjacent (8-conn) to po's cells, preferably keeping overlap? use min manhattan of origins with adjacency constraint
                pcells=po[1]; ocells=o[1]
                pset=set(pcells)
                oy=min(y for y,x in o[1]); ox=min(x for y,x in o[1])
                hh=max(a for a,b in norm(o[1]))+1; ww=max(b for a,b in norm(o[1]))+1
                for dy in range(-hh,H):
                    for dx in range(-ww,W):
                        cells={(dy+a,dx+b) for a,b in norm(o[1])}
                        adj=False
                        for y,x in cells:
                            if any((y+dy2,x+dx2) in pset for dy2 in(-1,0,1) for dx2 in(-1,0,1)): adj=True
                        if adj:
                            cost=abs(dy-oy)+abs(dx-ox)
                            if best is None or cost<best[0]: best=(cost,dy-oy,dx-ox)
            cands.append((best[0] if best else 0, o, best[1:] if best else None))
        cands.sort(key=lambda t:t[0])
        cost,o,shift=cands[0]
        if shift is None:
            placed.append((o[0],set(o[1])))
            unplaced.remove(o)
        else:
            newcells={(o[1][i][0]+shift[0],o[1][i][1]+shift[1]) for i in range(len(o[1]))}
            placed.append((o[0],newcells))
            unplaced.remove(o)
    # noise: recolor to color of adjacent placed object if adjacent, else delete
    out=[[bg]*len(I[0]) for _ in range(len(I))]
    clusters=[]
    for c,cells in placed: clusters.append((c,cells))
    # draw clusters
    for c,cells in placed:
        for y,x in cells: out[y][x]=c
    for cc,(y,x) in singles:
        adjcols={c for c,cells in clusters if any((y+dy,x+dx) in cells for dy in(-1,0,1) for dx in(-1,0,1))}
        if adjcols:
            out[y][x]=list(adjcols)[0]
        # else leave bg (deleted)
    return out

