                    cands.append((abs(dy-oy)+abs(dx-ox),dy-oy,dx-ox,frozenset(cells)))
        sols.append((c,cands))
    def backtrack(i,used,cur):
        if i==len(sols):
            yield frozenset((v[2]-c[1]*1, v[3]-c[0]*1) for c,v in zip([p[1] for p in objs], [0]*len(objs))), cur
            return
        c,cands=sols[i]
        for cost,s,d,cells in cands:
            if cells & used: continue
            yield from backtrack(i+1, used|cells, cur+[(c,s,d,cells)])
    results=list(backtrack(0, frozenset(), []))
    return sols,results
