def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=g[i][j]; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                out.append((c,cells))
    return out
def norm(cs):
    my=min(a for a,b in cs); mx=min(b for a,b in cs)
    return sorted((a-my,b-mx) for a,b in cs)

