def objs(G,bg):
    Hh,Ww=len(G),len(G[0]); seen=[[False]*Ww for _ in range(Hh)]; res=[]
    for i in range(Hh):
        for j in range(Ww):
            if G[i][j]!=bg and not seen[i][j]:
                stack=[(i,j)]; comp=[]
                while stack:
                    a,b=stack.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; comp.append((a,b,G[a][b]))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<Hh and 0<=y<Ww and not seen[x][y] and G[x][y]==G[a][b]:
                                stack.append((x,y))
                res.append(comp)
    return res
