        for k in order[1:]:
            target=min(order[:k],key=lambda kk:max(b for a,b in placed[kk]))
            cur=min(b for a,b in placed[k])
            tgt=max(b for a,b in placed[target])
            if cur<=tgt+1: continue
            # slide left until adjacent
            step=cur-(tgt+2)
            if step<=0: continue
            newcol={b-step for a,b in placed[k]}
            # check collisions with any other obj (orthogonal or diagonal adjacency counts as stop?)
