            # use simple: allow overlap-free
            collide=any(any(abs(a-b_)+abs(c-d_)>=1 for a_,b_ in placed[kk] for b_,d_ in [(ba,bd) for ba,bd in placed[k]]) for kk in order if kk!=k)
            # direct check: after shift, does any cell of placed[k] touch (8-adj) a different obj?
            others=set().union(*[placed[j] for j in order if j!=k])
            for a,b in placed[k]:
                nb={(a+da,b+db) for da in(-1,0,1) for db in(-1,0,1)}
                if (nb-others)&others: ok=False; break
            if not ok: break
            placed[k]={(a,b-step) for a,b in placed[k]}
            changed=True
    return res
