from collections import deque,Counter
def load3():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    base=d+'/../../sessions/'
    G={}
    for p in glob.glob(base+'*.jsonl'):
        txt=open(p).read().replace('\\n','\n')
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',txt):
            k,h,w=m[1],int(m[2]),int(m[3])
            rows=[r.split() for r in txt[m.end():].split('\n')[:h]]
            okk=False
            for row in rows:
                if len(row)!=w: okk=False;break
                for x in row:
                    if x.isdigit()==False: okk=False;break
            if okk and k not in G:
                G[k]=[[int(x) for x in r] for r in rows]
    return G
